<?php

namespace App\Http\Requests;

use Illuminate\Foundation\Http\FormRequest;

class EmployeeRequest extends FormRequest
{
    public function authorize(): bool
    {
        return true;
    }

    public function rules(): array
    {
        $isCreate = !$this->route('id');

        return [
            // Identity (EmpID is generated by the server)
            'BiometricID'   => ['nullable', 'string', 'max:50'],
            'EmpName'       => ['required', 'string', 'max:150'],
            'EmpFirstName'  => ['nullable', 'string', 'max:100'],
            'EmpMiddleName' => ['nullable', 'string', 'max:100'],
            'EmpLastName'   => ['nullable', 'string', 'max:100'],
            'Photo'         => ['nullable', 'image', 'max:2048'],

            // Contact
            'Address'          => ['nullable', 'string', 'max:255'],
            'PermanentAddress' => ['nullable', 'string', 'max:255'],
            'PresentAddress'   => ['nullable', 'string', 'max:255'],
            'ContactNo'        => ['nullable', 'string', 'max:50'],
            'EmailAdd'         => ['nullable', 'email', 'max:150'],
            'ContactPerson'    => ['nullable', 'string', 'max:150'],
            'ContactPersonNo'  => ['nullable', 'string', 'max:50'],

            // Personal
            'BirthDate'             => ['nullable', 'date'],
            'Gender'                => ['nullable', 'string', 'max:20'],
            'Religion'              => ['nullable', 'string', 'max:50'],
            'CivilStatus'           => ['nullable', 'string', 'max:30'],
            'MotherMaidenFullName'  => ['nullable', 'string', 'max:150'],
            'FatherFullName'        => ['nullable', 'string', 'max:150'],
            'HighestEducationalAtt' => ['nullable', 'string', 'max:100'],
            'NameOfSchool'          => ['nullable', 'string', 'max:150'],
            'DegreeCourse'          => ['nullable', 'string', 'max:150'],
            'HighestLevel'          => ['nullable', 'string', 'max:100'],

            // Employment
            'Department'   => ['required', 'string', 'max:100'],
            'Designation'  => ['required', 'string', 'max:100'],
            'DateEmployed' => ['nullable', 'date'],
            'EmpStatus'    => ['nullable', 'string', 'max:30'],
            'RecordStatus' => ['required', 'string', 'max:20'],
            'ProjectId'    => ['nullable', 'integer'],
            'ProjectName'  => ['nullable', 'string', 'max:150'],

            // Government
            'Tax'          => ['nullable', 'boolean'],
            'SSS'          => ['nullable', 'boolean'],
            'Pagibig'      => ['nullable', 'boolean'],
            'PhilHealth'   => ['nullable', 'boolean'],
            'Insurance'    => ['nullable', 'boolean'],
            'TIN'          => ['nullable', 'string', 'max:50'],
            'SSSNo'        => ['nullable', 'string', 'max:50'],
            'PhilHealthNo' => ['nullable', 'string', 'max:50'],
            'PagibigNo'    => ['nullable', 'string', 'max:50'],
            'InsuranceNo'  => ['nullable', 'string', 'max:50'],
            'SSSFId'       => ['nullable', 'integer'],
            'TaxFId'       => ['nullable', 'integer'],
            'PagibigFId'   => ['nullable', 'integer'],
            'PhilFId'      => ['nullable', 'integer'],
            'InsFId'       => ['nullable', 'integer'],
            'SSSER'        => ['nullable', 'numeric', 'min:0'],
            'PhilHealthER' => ['nullable', 'numeric', 'min:0'],
            'PagibigER'    => ['nullable', 'numeric', 'min:0'],

            // Salary
            'Salary'          => ['required', 'numeric', 'min:0'],
            'SalaryType'      => ['nullable', 'string', 'max:30'],
            'SalaryDate'      => ['nullable', 'date'],
            'SalaryStatus'    => ['nullable', 'string', 'max:30'],
            'StartPayroll'    => ['nullable', 'date'],
            'PayrollType'     => ['required', 'string', 'max:50'],
            'Allowance'       => ['nullable', 'numeric', 'min:0'],
            'AllowanceType'   => ['nullable', 'string', 'max:50'],
            'BankAccountNo'   => ['nullable', 'string', 'max:50'],
            'AllowOvertime'   => ['nullable', 'boolean'],
            'SaturdayHalfDay' => ['nullable', 'boolean'],

            // Shift and schedule
            'ShiftId'       => ['nullable', 'integer'],
            'Shift'         => ['nullable', 'string', 'max:100'],
            'LateAfter'     => ['nullable', 'numeric', 'min:0'],
            'OvertimeAfter' => ['nullable', 'numeric', 'min:0'],
            'DutyHours'     => ['nullable', 'numeric', 'min:0'],
            'HasBreakShift' => ['nullable', 'boolean'],
            'BreakShift'    => ['nullable', 'string', 'max:100'],
            'HasLunchShift' => ['nullable', 'boolean'],
            'LunchShift'    => ['nullable', 'string', 'max:100'],
            'IsNightShift'  => ['nullable', 'boolean'],
            'IsNextDayOut'  => ['nullable', 'boolean'],
            'FlexLunchMins' => ['nullable', 'integer', 'min:0'],
            'FlexBreakMins' => ['nullable', 'integer', 'min:0'],
            'DayOff'        => ['nullable', 'string', 'max:20'],
            'DayOff2'       => ['nullable', 'string', 'max:20'],
            'ScheduleType'  => ['nullable', 'string', 'max:30'],
            'IsDTRInput'    => ['nullable', 'boolean'],
            'DTRStatus'     => ['nullable', 'string', 'max:30'],

            // Passwords: required on create, blank on update keeps the current one
            'Password'         => ['nullable', 'string', 'min:6', 'max:100'],
            'TimecardPassword' => ['nullable', 'string', 'max:100'],
        ];
    }
}
